  select 1 from public.communities c
   where c.id = story_highlights.community_id
     and c.tenant_id = app.tenant_id()
     and c.kind = 'member'
     and c.created_by_user_id = app.user_id())));--> statement-breakpoint
CREATE POLICY "story_highlights_member_update_gate" ON "story_highlights" AS RESTRICTIVE FOR UPDATE TO "authenticated" USING (app.tenant_role() <> 'member' or (app.tenant_role() = 'member' and exists (
  select 1 from public.communities c
   where c.id = story_highlights.community_id
     and c.tenant_id = app.tenant_id()
     and c.kind = 'member'
     and c.created_by_user_id = app.user_id()))) WITH CHECK (app.tenant_role() <> 'member' or (app.tenant_role() = 'member' and exists (
  select 1 from public.communities c
   where c.id = story_highlights.community_id
     and c.tenant_id = app.tenant_id()
     and c.kind = 'member'
     and c.created_by_user_id = app.user_id())));--> statement-breakpoint
CREATE POLICY "story_highlights_member_delete_gate" ON "story_highlights" AS RESTRICTIVE FOR DELETE TO "authenticated" USING (app.tenant_role() <> 'member' or (app.tenant_role() = 'member' and exists (
  select 1 from public.communities c
   where c.id = story_highlights.community_id
     and c.tenant_id = app.tenant_id()
     and c.kind = 'member'
     and c.created_by_user_id = app.user_id())));--> statement-breakpoint
ALTER POLICY "feed_posts_social_insert_gate" ON "feed_posts" TO authenticated WITH CHECK ((app.tenant_role() = 'member' and visibility = 'followers' and community_id is null and (select app.social_enabled())) or (app.tenant_role() <> 'member' and visibility = 'tenant' and (community_id is null or exists (select 1 from public.communities c where c.id = community_id and c.tenant_id = app.tenant_id() and c.kind = 'organization'))) or (app.tenant_role() = 'member' and visibility = 'community' and community_id is not null and (select app.social_enabled()) and exists (select 1 from public.communities c where c.id = community_id and c.tenant_id = app.tenant_id() and c.kind = 'member' and c.created_by_user_id = app.user_id() and c.status = 'active' and c.deleted_at is null)) or (app.tenant_role() = 'member' and visibility = 'community' and community_id is not null and app.community_action_allowed(community_id, 'post')));

--> statement-breakpoint
-- HALF 2, statement 1 of 2 (hand-written): the BEFORE UPDATE guard of `public.stories` for the MEMBER lane (WR-03).
-- SECURITY INVOKER (the default, said here on purpose): it reads only OLD, NEW and the claims, so it needs no elevated right,
-- and a definer would be a standing way to bypass the policies it backs up. `set search_path = ''`, fully qualified names, no
-- single-row pick clause (pgTAP 040 pins the set of app functions that use one).
create or replace function app.stories_member_update_guard() returns trigger
  language plpgsql set search_path = '' as $$
begin
  if coalesce(app.tenant_role(), '') <> 'member' then
    return new;
  end if;

  -- a story the caller did not write (also covers a null user): only the two counters may change
  if old.author_user_id is distinct from app.user_id()
     and (to_jsonb(new) - array['like_count', 'comment_count'])
         is distinct from (to_jsonb(old) - array['like_count', 'comment_count']) then
    raise exception 'a member may only move the counters of a story it did not write'
      using errcode = '42501';
  end if;

  -- whatever the author, these four are fixed at insert (D-705, D-716)
  if new.author_user_id is distinct from old.author_user_id
     or new.visibility is distinct from old.visibility
     or new.tenant_id is distinct from old.tenant_id
     or new.media_asset_id is distinct from old.media_asset_id then
    raise exception 'a member may not change the author, audience, tenant or media of a story'
      using errcode = '42501';
  end if;

  -- the allow-list of the author: the counters and the soft delete, nothing else
  if (to_jsonb(new) - array['like_count', 'comment_count', 'deleted_at'])
     is distinct from (to_jsonb(old) - array['like_count', 'comment_count', 'deleted_at']) then
    raise exception 'a member author may change only the counters and the soft delete of a story'
      using errcode = '42501';
  end if;

  -- deleted_at: unchanged, or exactly the service's transition (live -> deleted), never back
  if new.deleted_at is distinct from old.deleted_at
     and not (old.deleted_at is null and new.deleted_at is not null) then
    raise exception 'a member author may change only the counters and the soft delete of a story'
      using errcode = '42501';
  end if;

  return new;
end
$$;
--> statement-breakpoint
grant execute on function app.stories_member_update_guard() to authenticated, service_role, api_user;
--> statement-breakpoint
create trigger stories_member_update_guard before update on public.stories
  for each row execute function app.stories_member_update_guard();
